const API_PATTERN = new URLPattern({ pathname: '/api/:version/:resource+' });
const STATIC_PATTERN = new URLPattern({ pathname: '/static/*' });

self.addEventListener('fetch', (event) => {
  const url = event.request.url;

  if (STATIC_PATTERN.test(url)) {
    // 静态资源走缓存优先策略
    event.respondWith(caches.match(event.request).then(
      cached => cached || fetch(event.request)
    ));
    return;
  }

  const apiMatch = API_PATTERN.exec(url);
  if (apiMatch) {
    const { version, resource } = apiMatch.pathname.groups;
    // 根据 API 版本和资源类型决定缓存策略
    event.respondWith(handleApiRequest(event.request, version, resource));
    return;
  }
});

const routes = [
  {
    pattern: new URLPattern({ pathname: '/api/users/:id' }),
    handler: (req, match) => {
      const { id } = match.pathname.groups;
      return new Response(JSON.stringify({ userId: id }), {
        headers: { 'Content-Type': 'application/json' }
      });
    }
  },
  {
    pattern: new URLPattern({ pathname: '/api/posts/:slug' }),
    handler: (req, match) => {
      const { slug } = match.pathname.groups;
      return new Response(JSON.stringify({ post: slug }));
    }
  }
];

// 请求处理
function handleRequest(request) {
  for (const route of routes) {
    const match = route.pattern.exec(request.url);
    if (match) {
      return route.handler(request, match);
    }
  }
  return new Response('Not Found', { status: 404 });
}
